from __future__ import annotations


def render_kuzu_3d_preview_page() -> str:
    """Render an additive Canvas pseudo-3D relationship investigation preview."""
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>关系网络 3D 预览</title><style>
:root{color-scheme:dark;font-family:"Microsoft YaHei","Segoe UI",sans-serif;background:#020b18;color:#e7f5ff}*{box-sizing:border-box}body{margin:0;overflow:hidden;background:#020b18}.top{height:70px;display:flex;align-items:center;gap:17px;padding:0 20px;border-bottom:1px solid #1c4f73;background:#041326dd}.top h1{font-size:24px;margin:0}.sub{color:#78a9cf;font-size:13px}.back,.btn{color:#c9eaff;text-decoration:none;border:1px solid #3378a8;background:#0b2844;border-radius:8px;padding:9px 13px;cursor:pointer}.btn.primary{background:#087fdc}.tools{margin-left:auto;display:flex;gap:8px;align-items:center}.tools input{width:70px;padding:8px;border:1px solid #356788;border-radius:6px;background:#071d31;color:#fff}.stage{height:calc(100vh - 70px);display:grid;grid-template-columns:220px minmax(600px,1fr) 330px}.overview{position:relative;border-right:1px solid #205072;background:#061629e8;padding:12px;overflow:hidden}.overview h2{font-size:15px;margin:0 0 6px}.overview p{font-size:11px;color:#88accd;line-height:1.4;margin:0 0 8px}.overview canvas{width:100%;height:260px;display:block;border:1px solid #1f5375;border-radius:8px;background:#041221;cursor:crosshair}.scene{position:relative;min-width:0}canvas{width:100%;height:100%;display:block;cursor:grab;touch-action:none}canvas.drag{cursor:grabbing}.hud{position:absolute;left:18px;top:16px;padding:10px 12px;border:1px solid #235878;border-radius:9px;background:#06182dcc;color:#8ec8ec;font-size:12px;line-height:1.65}.hud b{color:#e9f8ff}.loading{position:absolute;inset:0;display:grid;place-items:center;color:#8fd5ff;background:#03101ddd;font-size:17px}.loading[hidden]{display:none}.radar{width:64px;height:64px;border:1px solid #2fcaff;border-radius:50%;margin:auto auto 12px;position:relative;background:repeating-radial-gradient(circle,#2fcaff22 0 1px,transparent 2px 15px)}.radar:after{content:"";position:absolute;inset:0;border-radius:50%;background:conic-gradient(#2fcaff66,transparent 28%);animation:spin 1.25s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.side{border-left:1px solid #205072;background:#061629e8;padding:18px;overflow:auto}.side h2{margin:0 0 5px;font-size:20px}.side p{color:#89acd0;font-size:13px;line-height:1.55}.card{background:#0a2741;border:1px solid #275a7e;border-radius:10px;padding:12px;margin:12px 0}.card h3{margin:0 0 8px;font-size:14px}.muted{color:#8eafd0;font-size:12px;line-height:1.55}.path{padding:8px;border-left:3px solid #40cfff;background:#071d33;margin:7px 0;font-size:12px}.legend{display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:12px;color:#a2c2df}.legend i{font-style:normal}.legend i:before{content:"";display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--c);margin-right:5px}.tip{position:absolute;pointer-events:none;display:none;background:#06182fee;border:1px solid #4ba9db;border-radius:7px;padding:7px 9px;font-size:12px}@media(max-width:900px){.stage{grid-template-columns:1fr}.overview{display:none}.side{display:none}}
</style></head><body><div data-graph-type="focus-3d" hidden>3D 关系网络预览</div><header class="top"><a class="back" href="/kuzu-risk?graph_type=choose">← 图类型</a><h1>关系网络 3D 预览</h1><span class="sub">空间深度 · 聚合关系 · 路径审计</span><div class="tools"><label>阈值 <input id="threshold" type="number" min="1" max="100" value="12"></label><button class="btn primary" id="reload">重新计算</button><button class="btn" id="twoD">2D 主图</button><button class="btn" id="galaxy">星系图</button></div></header><main class="stage"><aside class="overview"><h2>2D 俯视定位</h2><p>固定从上方查看中心账户与各层节点位置。旋转 3D 时此图保持稳定。</p><canvas id="overview" aria-label="3D关系网络二维俯视图"></canvas><div class="muted">中心账户固定在中央；点击节点可同步选中。</div></aside><section class="scene"><canvas id="scene" aria-label="可旋转的三维账户关系网络"></canvas><div class="hud"><b>操作</b><br>拖动：旋转空间　滚轮：缩放<br>点击：高亮到中心的路径<br><span id="meta">等待数据</span></div><div id="loading" class="loading"><div><div class="radar"></div>正在读取关系并建立空间投影…</div></div><div id="tip" class="tip"></div></section><aside class="side"><h2 id="title">选择一个节点</h2><p id="intro">中心账户固定在空间原点。关系实体位于账户之间，扩散圈层沿纵深展开。</p><div id="body" class="card"><div class="muted">加载完成后，点击球体或关系实体查看链路。</div></div><div class="card"><h3>当前 3D 规则</h3><div class="muted">红色大球：中心账户<br>彩色球体：关联账户<br>发光菱形：关系实体<br>空间深度：扩散层级<br>暗线：背景证据；亮线：选中路径</div></div><div class="legend"><i style="--c:#56aaf5">同 CRM</i><i style="--c:#a78bfa">LastIP</i><i style="--c:#22d3ee">EA</i><i style="--c:#f472b6">跟单</i><i style="--c:#fbbf24">返佣 / IB</i><i style="--c:#34d399">同名</i></div></aside></main>
<script>(()=>{const q=new URLSearchParams(location.search),account=q.get('account')||'',platform=q.get('platform')||'',server=q.get('server')||'',canvas=document.getElementById('scene'),ctx=canvas.getContext('2d'),overview=document.getElementById('overview'),octx=overview.getContext('2d'),loading=document.getElementById('loading'),meta=document.getElementById('meta'),title=document.getElementById('title'),intro=document.getElementById('intro'),body=document.getElementById('body'),tip=document.getElementById('tip');const COLORS={same_crm_user:'#56aaf5',crm_owner:'#56aaf5',login_ip:'#a78bfa',ea_feature:'#22d3ee',copy_order:'#f472b6',copy_group:'#f472b6',rebate:'#fbbf24',direct_ib:'#fbbf24',ib_owned_account:'#fbbf24',ib_direct_account:'#fbbf24',ib_identity:'#fbbf24',ib_direct_rebate:'#fbbf24',top_ib_group:'#fbbf24',same_name:'#34d399',toxic_sync_same:'#fb7185',toxic_sync_opposite:'#fb7185'};const S={nodes:[],edges:[],by:new Map(),subject:'',yaw:-.48,pitch:.34,distance:980,selected:'',hover:'',drag:null,raf:0,generation:0};const id=v=>String(v??'').trim(),esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])),hash=s=>{let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return(h>>>0)/4294967296},color=e=>COLORS[e.type]||'#6a96bd',status=n=>id(n.databaseStatus||n.status||'B').toUpperCase()||'B';
function endpoint(){const p=new URLSearchParams({threshold:String(document.getElementById('threshold').value||12),include_toxic:'false'});if(platform)p.set('platform',platform);if(server)p.set('server',server);return account?'/api/accounts/by-login/'+encodeURIComponent(account)+'/relationship-network?'+p:'/api/kuzu-risk/graph?threshold='+p.get('threshold')}
function normalize(payload){const g=payload?.presentationGraph||payload,raw=Array.isArray(g?.entities)?g.entities:[];S.nodes=raw.map((n,i)=>({...n,id:id(n.id||n.account||n.label||i),status:status(n),x:0,y:0,z:0,screen:null}));S.subject=id(g?.subjectId)||S.nodes.find(n=>n.isSubject||n.subject)?.id||S.nodes[0]?.id||'';S.by=new Map(S.nodes.map(n=>[n.id,n]));S.edges=(g?.relationships||[]).map((e,i)=>({...e,id:id(e.id)||'e'+i,source:id(e.source||e.from),target:id(e.target||e.to),type:id(e.type),label:e.typeLabel||e.label||e.type||'关系'})).filter(e=>S.by.has(e.source)&&S.by.has(e.target));const levels=new Map();S.nodes.forEach(n=>{if(n.id===S.subject)return;n.h=Math.max(1,Number(n.hops||1));if(!levels.has(n.h))levels.set(n.h,[]);levels.get(n.h).push(n)});for(const [h,list] of levels){list.sort((a,b)=>a.id.localeCompare(b.id));list.forEach((n,i)=>{const u=(i+.5)/Math.max(1,list.length),theta=Math.acos(1-2*u),phi=i*2.3999632297+hash(n.id)*.45,r=175+h*95+(n.type==='account'?25:-30);n.x=r*Math.sin(theta)*Math.cos(phi);n.y=r*Math.cos(theta);n.z=r*Math.sin(theta)*Math.sin(phi)})}const sub=S.by.get(S.subject);if(sub){sub.x=sub.y=sub.z=0}S.selected=S.subject;meta.textContent=`${S.nodes.length} 节点 · ${S.edges.length} 条关系`;render();show(S.subject)}
function resize(){const d=devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight,ow=overview.clientWidth,oh=overview.clientHeight;if(canvas.width!==Math.round(w*d)||canvas.height!==Math.round(h*d)){canvas.width=Math.round(w*d);canvas.height=Math.round(h*d)}if(overview.width!==Math.round(ow*d)||overview.height!==Math.round(oh*d)){overview.width=Math.round(ow*d);overview.height=Math.round(oh*d)}ctx.setTransform(d,0,0,d,0,0);octx.setTransform(d,0,0,d,0,0);return{w,h}}function project(n,w,h){const cy=Math.cos(S.yaw),sy=Math.sin(S.yaw),cp=Math.cos(S.pitch),sp=Math.sin(S.pitch),x=n.x*cy-n.z*sy,z=n.x*sy+n.z*cy,y=n.y*cp-z*sp,z2=n.y*sp+z*cp,scale=Math.max(.18,S.distance/(S.distance+z2+520));return{x:w/2+x*scale,y:h/2+y*scale,scale,depth:z2}}
function selectedPath(){const keep=new Set(),edges=new Set();if(!S.selected)return{keep,edges};let cur=S.selected;keep.add(cur);for(let guard=0;guard<30&&cur!==S.subject;guard++){const e=S.edges.find(x=>(x.source===cur||x.target===cur)&&!edges.has(x.id));if(!e)break;edges.add(e.id);cur=e.source===cur?e.target:e.source;keep.add(cur)}return{keep,edges}}function drawLine(a,b,c,width,alpha){ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=c;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(a.x,a.y);const bend=(a.depth-b.depth)*.045;ctx.quadraticCurveTo((a.x+b.x)/2+bend,(a.y+b.y)/2-bend,b.x,b.y);ctx.stroke();ctx.restore()}
function drawOverview(){const w=overview.clientWidth,h=overview.clientHeight;if(!w||!h)return;octx.clearRect(0,0,w,h);octx.fillStyle='#041221';octx.fillRect(0,0,w,h);const cx=w/2,cy=h/2,scale=Math.min(w,h)/2.25/Math.max(1,...S.nodes.map(n=>Math.hypot(n.x,n.z)));octx.save();octx.translate(cx,cy);octx.strokeStyle='#2b749955';octx.setLineDash([4,5]);for(let r=34;r<Math.min(w,h)/2;r+=34){octx.beginPath();octx.arc(0,0,r,0,Math.PI*2);octx.stroke()}const active=selectedPath();S.edges.forEach(e=>{const a=S.by.get(e.source),b=S.by.get(e.target);if(!a||!b)return;const on=active.edges.has(e.id);octx.globalAlpha=on?1:.18;octx.strokeStyle=on?'#54dcff':color(e);octx.lineWidth=on?2.2:0.8;octx.beginPath();octx.moveTo(a.x*scale,a.z*scale);octx.lineTo(b.x*scale,b.z*scale);octx.stroke()});S.nodes.forEach(n=>{const x=n.x*scale,y=n.z*scale,on=active.keep.has(n.id),r=n.id===S.subject?6:3.5;octx.globalAlpha=S.selected&&!on ? .28 : 1;octx.fillStyle=n.id===S.subject?'#ff3047':n.type==='account'?(n.riskColor||'#f25a43'):'#42cbed';octx.beginPath();octx.arc(x,y,r,0,Math.PI*2);octx.fill();if(n.id===S.subject){octx.strokeStyle='#fff';octx.lineWidth=2;octx.stroke()}});octx.restore();octx.fillStyle='#9fc4df';octx.font='11px Microsoft YaHei';octx.textAlign='center';octx.fillText('俯视图（X/Z）',cx, h-8)}function render(){const {w,h}=resize();ctx.clearRect(0,0,w,h);const bg=ctx.createRadialGradient(w/2,h/2,10,w/2,h/2,Math.max(w,h)*.68);bg.addColorStop(0,'#0b3553');bg.addColorStop(.42,'#061a2d');bg.addColorStop(1,'#020a15');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(w/2,h/2);ctx.strokeStyle='#2b749733';for(let r=100;r<Math.max(w,h);r+=120){ctx.beginPath();ctx.ellipse(0,0,r,r*.28,0,0,Math.PI*2);ctx.stroke()}ctx.restore();S.nodes.forEach(n=>n.screen=project(n,w,h));const active=selectedPath();[...S.edges].sort((a,b)=>((S.by.get(a.source)?.screen.depth||0)+(S.by.get(a.target)?.screen.depth||0))-((S.by.get(b.source)?.screen.depth||0)+(S.by.get(b.target)?.screen.depth||0))).forEach(e=>{const a=S.by.get(e.source)?.screen,b=S.by.get(e.target)?.screen;if(a&&b){const on=active.edges.has(e.id);drawLine(a,b,on?'#54dcff':color(e),on?3.5:1.1,on?1:.18)}});[...S.nodes].sort((a,b)=>a.screen.depth-b.screen.depth).forEach(n=>drawNode(n,active.keep.has(n.id)));drawOverview();if(S.selected){const n=S.by.get(S.selected);if(n?.screen){ctx.fillStyle='#9fe8ff';ctx.font='12px Microsoft YaHei';ctx.textAlign='center';ctx.fillText('当前选择',n.screen.x,n.screen.y-(n.isSubject?30:20)*n.screen.scale-19)}}S.raf=0}
function drawNode(n,onPath){const p=n.screen,isAccount=n.type==='account'||n.id===S.subject,base=n.id===S.subject?31:isAccount?19:15,r=Math.max(7,base*p.scale),fill=n.id===S.subject?'#ff3047':isAccount?(n.riskColor||'#f25a43'):(COLORS[n.relationType]||COLORS[n.type]||'#42cbed');ctx.save();ctx.globalAlpha=S.selected&&!onPath ? .3 : 1;ctx.translate(p.x,p.y);ctx.shadowBlur=onPath?20:8;ctx.shadowColor=fill;const g=ctx.createRadialGradient(-r*.32,-r*.34,2,0,0,r);g.addColorStop(0,'#fff');g.addColorStop(.16,fill);g.addColorStop(1,'#081a2c');ctx.fillStyle=g;ctx.strokeStyle=onPath?'#e9fbff':'#74b4d5';ctx.lineWidth=onPath?3:1.2;ctx.beginPath();if(isAccount)ctx.arc(0,0,r,0,Math.PI*2);else{ctx.moveTo(0,-r);ctx.lineTo(r,0);ctx.lineTo(0,r);ctx.lineTo(-r,0);ctx.closePath()}ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#06111d';ctx.font=`900 ${Math.max(9,r*.58)}px Microsoft YaHei`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(isAccount?n.status:'◆',0,0);if(n.id===S.subject||n.id===S.selected||n.id===S.hover||!isAccount){ctx.fillStyle='#e7f5ff';ctx.font='12px Microsoft YaHei';ctx.textBaseline='top';ctx.fillText(n.label||n.account||n.id,0,r+7)}ctx.restore();p.r=r}
function schedule(){if(!S.raf)S.raf=requestAnimationFrame(render)}function nearest(x,y){let best=null,d=32;for(const n of S.nodes){if(!n.screen)continue;const q=Math.hypot(x-n.screen.x,y-n.screen.y);if(q<Math.max(d,n.screen.r+8)){d=q;best=n}}return best}function show(nodeId){const n=S.by.get(nodeId);if(!n)return;const inc=S.edges.filter(e=>e.source===nodeId||e.target===nodeId);title.textContent=(n.type==='account'||n.id===S.subject?'账户 ':'关系实体 ')+(n.label||n.account||n.id);intro.textContent=n.id===S.subject?'这是调查起点，位于三维空间原点。':`第 ${n.hops||0} 层；已高亮其到中心账户的证据路径。`;body.innerHTML=`<h3>状态 ${esc(n.status)}</h3><div class="muted">分值 ${Number(n.score||0).toFixed(1)} · ${esc(n.platform||platform)} ${esc(n.server||server)}</div>${inc.map(e=>`<div class="path" style="border-color:${color(e)}"><b>${esc(e.label)}</b><br>${esc(e.source)} → ${esc(e.target)}</div>`).join('')||'<div class="muted">暂无直接关系边</div>'}`}
overview.addEventListener('pointerup',e=>{const r=overview.getBoundingClientRect(),w=overview.clientWidth,h=overview.clientHeight,cx=w/2,cy=h/2,scale=Math.min(w,h)/2.25/Math.max(1,...S.nodes.map(n=>Math.hypot(n.x,n.z))),x=(e.clientX-r.left-cx)/scale,y=(e.clientY-r.top-cy)/scale;let best=null,dist=16;for(const n of S.nodes){const d=Math.hypot(n.x-x,n.z-y);if(d<dist){dist=d;best=n}}if(best){S.selected=best.id;show(best.id);schedule()}});canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);S.drag={x:e.clientX,y:e.clientY,moved:false};canvas.classList.add('drag')});canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(S.drag){const dx=e.clientX-S.drag.x,dy=e.clientY-S.drag.y;if(Math.abs(dx)+Math.abs(dy)>2)S.drag.moved=true;S.yaw+=dx*.008;S.pitch=Math.max(-1.25,Math.min(1.25,S.pitch+dy*.006));S.drag.x=e.clientX;S.drag.y=e.clientY;schedule()}else{const n=nearest(x,y);S.hover=n?.id||'';tip.style.display=n?'block':'none';if(n){tip.textContent=(n.label||n.account||n.id)+' · '+n.status;tip.style.left=(x+14)+'px';tip.style.top=(y+14)+'px'}schedule()}});canvas.addEventListener('pointerup',e=>{if(S.drag&&!S.drag.moved){const r=canvas.getBoundingClientRect(),n=nearest(e.clientX-r.left,e.clientY-r.top);if(n){S.selected=n.id;show(n.id);schedule()}}S.drag=null;canvas.classList.remove('drag')});canvas.addEventListener('wheel',e=>{e.preventDefault();S.distance=Math.max(260,Math.min(2400,S.distance*(e.deltaY>0?1.12:.88)));schedule()},{passive:false});window.addEventListener('resize',schedule);
async function load(){const generation=++S.generation;loading.hidden=false;try{for(let i=0;i<180;i++){const r=await fetch(endpoint(),{cache:'no-store'});if(!r.ok)throw new Error('关系接口返回 '+r.status);const p=await r.json();if(generation!==S.generation)return;normalize(p);loading.hidden=true;if(!p.inProgress)return;await new Promise(ok=>setTimeout(ok,650))}}catch(e){loading.innerHTML='<div>'+esc(e.message||e)+'</div>'}}function go(type){const u=new URL('/kuzu-risk',location.origin);q.forEach((v,k)=>u.searchParams.set(k,v));u.searchParams.set('graph_type',type);location.assign(u)}document.getElementById('reload').onclick=load;document.getElementById('twoD').onclick=()=>go('focus-force');document.getElementById('galaxy').onclick=()=>go('galaxy');load()})();</script></body></html>'''
